PrUnicodeBidiClass prUnicodeBidiClass(uint32_t codePoint) {
    return PrUnicodeBidiClass(unicodeStagedValue(kBidiClassTop, kBidiClassMiddle, kBidiClassLeaves, codePoint));
}

PrUnicodeBidiBracket prUnicodeBidiBracket(uint32_t codePoint, uint32_t* key) {
    uint32_t at = lowerBound(Span(kBidiBrackets), codePoint);
    if (at == countOf(kBidiBrackets) || kBidiBrackets[at] != codePoint)
        return PrUnicodeBidiBracket_None;
    *key = kBidiBracketKeys[at] >> 1;
    return (kBidiBracketKeys[at] & 1) != 0 ? PrUnicodeBidiBracket_Open : PrUnicodeBidiBracket_Close;
}

uint32_t prUnicodeBidiMirror(uint32_t codePoint) {
    uint32_t at = lowerBound(Span(kBidiMirrored), codePoint);
    return at != countOf(kBidiMirrored) && kBidiMirrored[at] == codePoint ? kBidiMirrors[at] : codePoint;
}

bool prUnicodeBidiIsMirrored(uint32_t codePoint) {
    uint32_t at = lowerBound(Span(kBidiMirroredProperty), codePoint);
    return at != countOf(kBidiMirroredProperty) && kBidiMirroredProperty[at] == codePoint;
}

